const http=require('http'),fs=require('fs'),path=require('path'),cr=require('crypto');
const FILE=path.join(__dirname,'data2.json'),RU=(process.env.UPSTASH_REDIS_REST_URL||'').replace(/\/$/,''),RT=process.env.UPSTASH_REDIS_REST_TOKEN||'',LIM=Infinity;
let D={logins:{},profiles:{},tokens:{},friends:{},groups:{},msgs:[],reads:{},n:1,pf:{},seen:{},pins:{},blocks:{},ttl:{}};
if(!RU)try{D=Object.assign(D,JSON.parse(fs.readFileSync(FILE,'utf8')))}catch{}
let dirty=false,busy=false;const save=()=>{dirty=true};
async function flush(){if(!dirty||busy)return;dirty=false;busy=true;const s=JSON.stringify(D);
  try{if(RU){const r=await fetch(RU,{method:'POST',headers:{Authorization:'Bearer '+RT},body:JSON.stringify(['SET','byrex',s])});if(!r.ok)throw new Error('save failed '+r.status)}else fs.writeFileSync(FILE,s)}
  catch(e){console.error(e.message);dirty=true}busy=false}
setInterval(flush,RU?4000:1000);
for(const sg of['SIGTERM','SIGINT'])process.on(sg,async()=>{busy=false;imBusy=false;await flush();await flushIm();process.exit(0)});
const IMF=path.join(__dirname,'img2.json');let IM={};
if(!RU)try{IM=JSON.parse(fs.readFileSync(IMF,'utf8'))}catch{}
let imDirty=false,imBusy=false;
async function flushIm(){if(!imDirty||imBusy)return;imDirty=false;imBusy=true;const s=JSON.stringify(IM);
  try{if(RU){const r=await fetch(RU,{method:'POST',headers:{Authorization:'Bearer '+RT},body:JSON.stringify(['SET','byrex-img',s])});if(!r.ok)throw new Error('img save failed '+r.status)}else fs.writeFileSync(IMF,s)}
  catch(e){console.error(e.message);imDirty=true}imBusy=false}
setInterval(flushIm,RU?4000:1000);
const GK=process.env.GIPHY_KEY||'';
async function gifs(b){if(!GK)return{nokey:1,g:[]};const q=String(b.q||'').trim().slice(0,60);
  const url='https://api.giphy.com/v1/gifs/'+(q?'search':'trending')+'?api_key='+encodeURIComponent(GK)+'&limit=24&rating=pg-13'+(q?'&q='+encodeURIComponent(q):'');
  try{const r=await fetch(url),j=await r.json();
    return{g:(j.data||[]).map(x=>({p:x.images?.fixed_height_small?.url,u:x.images?.fixed_height?.url})).filter(x=>/^https:\/\//.test(x.p||'')&&/^https:\/\//.test(x.u||''))}}
  catch{return{err:'GIF search failed'}}}
const streams={};
const isOn=p=>{const o=D.profiles[p];return!!(streams[o]&&streams[o].size)};
const pres=L=>{const ps=(D.logins[L]||{profiles:[]}).profiles;push(ps.flatMap(p=>fr(p).f),{e:'sync'})};
const push=(ps,ev)=>{ps=[...new Set(ps)];ev.for=ps;const s='data: '+JSON.stringify(ev)+'\n\n';
  for(const o of new Set(ps.map(p=>D.profiles[p])))for(const r of streams[o]||[])r.write(s)};
const fr=p=>D.friends[p]||(D.friends[p]={f:[],i:[],o:[]});
const dmid=(a,b)=>'d:'+[a,b].sort().join('|');
const mem=c=>c[0]=='d'?c.slice(2).split('|'):(D.groups[c.slice(2)]||{members:[]}).members;
const sys=(c,t)=>{D.msgs.push({id:D.n++,c,f:'',t,ts:Date.now(),s:1})};
setInterval(()=>{if(!D.sched||!D.sched.length)return;const now=Date.now(),due=D.sched.filter(x=>x.at<=now);if(!due.length)return;
  for(const x of due){try{const m=mem(x.c);if(m.includes(x.f)){addM({c:x.c,f:x.f,t:x.t,...xp(x.c)});push(m,{e:'sync'})}}catch{}}
  D.sched=D.sched.filter(x=>x.at>now);save()},5000);
const xp=c=>D.ttl[c]?{x:Date.now()+D.ttl[c]*1000}:{};
const addM=o=>{D.msgs.push({id:D.n++,ts:Date.now(),...o});if(D.msgs.length>LIM)D.msgs.splice(0,500)};
const dmOk=(c,p)=>{if(c[0]!='d')return;const o=mem(c).find(x=>x!=p);if(!fr(p).f.includes(o))throw'You are not friends';
  if((D.blocks[o]||[]).includes(p)||(D.blocks[p]||[]).includes(o))throw'Cannot send'};
const RL={};const limited=ip=>{const now=Date.now(),a=(RL[ip]=(RL[ip]||[]).filter(t=>now-t<300000));a.push(now);return a.length>12};
const role=(g,p)=>g.owner==p?'owner':g.admins.includes(p)?'admin':'member';
const hash=(pw,salt)=>cr.scryptSync(pw,salt,32).toString('hex');
const nm=s=>String(s||'').trim().toLowerCase();
const okName=s=>/^[a-z0-9_]{3,20}$/.test(s);
const mkTok=l=>{const t=cr.randomBytes(24).toString('hex');D.tokens[t]=l;const mine=Object.keys(D.tokens).filter(k=>D.tokens[k]==l);while(mine.length>5)delete D.tokens[mine.shift()];save();return t};
const rm=(g,all)=>{delete D.groups[g.id];D.msgs=D.msgs.filter(m=>m.c!='g:'+g.id);save();push(all,{e:'sync'});return{}};

// ---- Google sign-in (optional: active only when GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET are set) ----
const GID=process.env.GOOGLE_CLIENT_ID||'',GSEC=process.env.GOOGLE_CLIENT_SECRET||'',GON=!!(GID&&GSEC);
const GSTATE={},GCODE={};
const gcl=()=>{const n=Date.now();for(const o of [GSTATE,GCODE])for(const k in o)if(o[k].exp<n)delete o[k]};
const gRedirect=q=>'https://'+(q.headers.host||'localhost')+'/auth/google/callback';
function gStart(q,s){
  if(!GON){s.writeHead(302,{Location:'/?gerr=off'});return s.end()}
  gcl();const st=cr.randomBytes(16).toString('hex');GSTATE[st]={exp:Date.now()+600000};
  const p=new URLSearchParams({client_id:GID,redirect_uri:gRedirect(q),response_type:'code',scope:'openid email profile',state:st,prompt:'select_account'});
  s.writeHead(302,{Location:'https://accounts.google.com/o/oauth2/v2/auth?'+p});s.end()}
function gUser(email){
  const hit=Object.keys(D.logins).find(k=>D.logins[k].g===email);if(hit)return hit;
  let base=String(email).split('@')[0].toLowerCase().replace(/[^a-z0-9_]/g,'').slice(0,16);
  if(base.length<3)base=(base+'user').slice(0,16);
  let u=base,i=2;while(D.profiles[u]||!okName(u))u=base.slice(0,16-String(i).length)+i++;
  const salt=cr.randomBytes(16).toString('hex');
  D.logins[u]={salt,hash:hash(cr.randomBytes(32).toString('hex'),salt),profiles:[u],g:email};D.profiles[u]=u;save();
  return u}
function gCallback(q,s,u){
  const bad=e=>{s.writeHead(302,{Location:'/?gerr='+e});return s.end()};
  if(!GON)return bad('off');
  const st=u.searchParams.get('state')||'',code=u.searchParams.get('code')||'';
  const ok=!!GSTATE[st]&&GSTATE[st].exp>Date.now()&&!!code;delete GSTATE[st];
  if(!ok)return bad('failed');
  fetch('https://oauth2.googleapis.com/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},
    body:new URLSearchParams({code,client_id:GID,client_secret:GSEC,redirect_uri:gRedirect(q),grant_type:'authorization_code'})})
    .then(r=>r.json()).then(t=>{if(!t.access_token)throw new Error('no access token');
      return fetch('https://openidconnect.googleapis.com/v1/userinfo',{headers:{Authorization:'Bearer '+t.access_token}})})
    .then(r=>r.json()).then(i=>{
      if(!i.email||!i.email_verified)throw new Error('email not verified');
      const user=gUser(String(i.email).toLowerCase());
      gcl();const c=cr.randomBytes(24).toString('hex');GCODE[c]={u:user,exp:Date.now()+120000};
      s.writeHead(302,{Location:'/#gcode='+c});s.end()})
    .catch(e=>{console.error('Google sign-in:',e.message);bad('failed')})}
function gexch(b){const c=String(b.c||''),x=GCODE[c];delete GCODE[c];
  if(!x||x.exp<Date.now()||!D.logins[x.u])throw'Sign-in expired. Try again.';
  return{token:mkTok(x.u),profiles:D.logins[x.u].profiles}}
function reg(b){const u=nm(b.u),pw=String(b.pw||'');
  if(!okName(u))throw'Username: 3-20 characters, a-z 0-9 _';
  if(pw.length<4)throw'Password is too short (min 4)';
  if(D.profiles[u])throw'Username is taken';
  const salt=cr.randomBytes(16).toString('hex');
  D.logins[u]={salt,hash:hash(pw,salt),profiles:[u]};D.profiles[u]=u;save();
  return{token:mkTok(u),profiles:[u]}}
// ---- two-step verification (TOTP, RFC 6238) ----
const B32='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567',PEND2={},PENDSET={};
const b32e=buf=>{let bits=0,v=0,o='';for(const x of buf){v=((v<<8)|x)&0xffff;bits+=8;while(bits>=5){o+=B32[(v>>>(bits-5))&31];bits-=5}}if(bits>0)o+=B32[(v<<(5-bits))&31];return o};
const b32d=s=>{let bits=0,v=0;const out=[];for(const c of String(s).toUpperCase().replace(/=+$/,'')){const i=B32.indexOf(c);if(i<0)continue;v=((v<<5)|i)&0xffff;bits+=5;if(bits>=8){out.push((v>>>(bits-8))&255);bits-=8}}return Buffer.from(out)};
const hotp=(key,ctr)=>{const b=Buffer.alloc(8);b.writeBigUInt64BE(BigInt(ctr));const h=cr.createHmac('sha1',key).update(b).digest();const o=h[h.length-1]&15;return String(((h.readUInt32BE(o)&0x7fffffff)%1000000)).padStart(6,'0')};
const otpOk=(o,code)=>{const key=b32d(o.secret),now=Date.now(),c=String(code||'').replace(/\s/g,'');for(const d of [-1,0,1]){const ctr=Math.floor((now+d*30000)/30000);if(c&&hotp(key,ctr)===c&&ctr>(o.last||0)){o.last=ctr;return true}}return false};
const recHash=s=>cr.createHash('sha256').update(String(s).toLowerCase().replace(/[^a-z0-9]/g,'')).digest('hex');
function otpLogin(b){const x=PEND2[String(b.tmp||'')];if(!x||x.exp<Date.now())throw'Code expired. Log in again.';
  const L=D.logins[x.u];if(!L||!L.otp||!L.otp.on)throw'Log in again';
  const code=String(b.code||'').trim();let ok=otpOk(L.otp,code);
  if(!ok){const i=(L.otp.rec||[]).indexOf(recHash(code));if(i>=0){L.otp.rec.splice(i,1);ok=true}}
  if(!ok)throw'Wrong code';
  save();delete PEND2[String(b.tmp)];return{token:mkTok(x.u),profiles:L.profiles}}
function pwReset(b){const u=nm(b.u),LL=D.logins[u],code=String(b.code||'').trim();
  if(!LL||!Array.isArray(LL.rc)||!LL.rc.length)throw'Wrong username or recovery code';
  const i=LL.rc.indexOf(recHash(code));if(i<0)throw'Wrong username or recovery code';
  const pw=String(b.pw||'');if(pw.length<4)throw'New password is too short (min 4)';
  LL.rc.splice(i,1);LL.salt=cr.randomBytes(16).toString('hex');LL.hash=hash(pw,LL.salt);
  for(const t of Object.keys(D.tokens))if(D.tokens[t]==u)delete D.tokens[t];
  save();return{}}
function login(b){const u=nm(b.u),L=D.logins[u];
  if(!L||hash(String(b.pw||''),L.salt)!==L.hash)throw'Wrong username or password';
  if(L.otp&&L.otp.on){const tmp=cr.randomBytes(18).toString('hex');PEND2[tmp]={u,exp:Date.now()+300000};return{need:'otp',tmp}}
  return{token:mkTok(u),profiles:L.profiles}}
function sync(p,L){const f=fr(p);
  const gs=Object.values(D.groups).filter(g=>g.members.includes(p));
  const ids=new Set([...f.f.map(x=>dmid(p,x)),...gs.map(g=>'g:'+g.id)]);
  const msgs={};for(const id of ids)msgs[id]=[];
  for(const m of D.msgs)if(ids.has(m.c))msgs[m.c].push(m);
  for(const k in msgs)msgs[k]=msgs[k].slice(-200);
  const rd={},pr={};
  for(const id of ids){rd[id]=D.reads[id+'#'+p]||0;if(id[0]=='d'){const o=mem(id).find(x=>x!=p);pr[id]=D.reads[id+'#'+o]||0}}
  const pins={},ttl={};for(const id of ids){if(D.pins[id])pins[id]=D.pins[id];if(D.ttl[id])ttl[id]=D.ttl[id]}
  const us=new Set([p,...f.f,...f.i,...f.o,...gs.flatMap(g=>g.members)]),pf={};for(const u of us)if(D.pf[u])pf[u]=D.pf[u];
  const ls={};for(const u of f.f)if(D.seen[u])ls[u]=D.seen[u];
  return{pf,ls,pins,ttl,bl:D.blocks[p]||[],me:p,profiles:D.logins[L].profiles,friends:f,groups:gs,msgs,rd,pr,on:f.f.filter(isOn),
    pub:Object.values(D.groups).filter(g=>g.pub&&!g.members.includes(p)).slice(0,50).map(g=>({id:g.id,name:g.name,n:g.members.length}))}}

function act(L,p,b){
  const g=D.groups[b.id];
  const adm=()=>{if(!g||!g.members.includes(p)||role(g,p)=='member')throw'Admins only'};
  switch(b.a){
  case'addp':{const u=nm(b.u);if(!okName(u))throw'Username: 3-20 characters, a-z 0-9 _';if(D.profiles[u])throw'Username is taken';
    D.logins[L].profiles.push(u);D.profiles[u]=L;save();return{profiles:D.logins[L].profiles}}
  case'sync':return sync(p,L);
  case'voice':{const d=String(b.d||'');
    if(d.length>190000||!/^data:audio\/(webm|ogg|mp4)(;[^,]*)?;base64,[A-Za-z0-9+\/=]+$/.test(d))throw'Voice message too long or bad format';
    const id=cr.createHash('sha1').update(d).digest('hex').slice(0,16);IM[id]={d,ts:Date.now()};
    let tot=Object.values(IM).reduce((a,x)=>a+x.d.length,0);const ks=Object.keys(IM).sort((x,y)=>IM[x].ts-IM[y].ts);
    while(tot>4000000&&ks.length>1){const k=ks.shift();if(k==id)continue;tot-=IM[k].d.length;delete IM[k]}
    imDirty=true;return{id}}
  case'img':{const d=String(b.d||'');
    if(d.length>80000||!/^data:image\/(png|webp|jpeg|gif);base64,[A-Za-z0-9+\/=]+$/.test(d))throw'Bad image (max about 60 KB)';
    const id=cr.createHash('sha1').update(d).digest('hex').slice(0,16);IM[id]={d,ts:Date.now()};
    let tot=Object.values(IM).reduce((a,x)=>a+x.d.length,0);const ks=Object.keys(IM).sort((x,y)=>IM[x].ts-IM[y].ts);
    while(tot>4000000&&ks.length>1){const k=ks.shift();if(k==id)continue;tot-=IM[k].d.length;delete IM[k]}
    imDirty=true;return{id}}
  case'prof':{const n=String(b.n||'').trim().slice(0,32),bio=String(b.b||'').trim().slice(0,200);
    if(n||bio)D.pf[p]={n,b:bio};else delete D.pf[p];save();push([p,...fr(p).f],{e:'sync'});return{}}
  case'pin':{const c=String(b.c),m=mem(c);if(!m.includes(p))throw'No access';
    if(c[0]=='g'&&role(D.groups[c.slice(2)],p)=='member')throw'Admins only';
    if(b.id){const x=D.msgs.find(y=>y.id==b.id&&y.c==c);if(!x||x.s)throw'Not allowed';D.pins[c]=x.id}else delete D.pins[c];
    save();push(m,{e:'sync'});return{}}
  case'fwd':{const src=D.msgs.find(x=>x.id==b.id);if(!src||src.s||!mem(src.c).includes(p))throw'Not allowed';
    if(src.poll)throw'Polls cannot be forwarded';const c=String(b.c),m=mem(c);if(!m.includes(p))throw'Cannot send';dmOk(c,p);
    addM({c,f:p,t:src.t,...(b.hide?{}:{fw:src.fw||src.f}),...xp(c)});save();push(m,{e:'sync'});return{}}
  case'poll':{const c=String(b.c),m=mem(c);if(!m.includes(p))throw'Cannot send';dmOk(c,p);
    const q=String(b.q||'').trim().slice(0,200),o=(Array.isArray(b.o)?b.o:[]).map(x=>String(x||'').trim().slice(0,80)).filter(Boolean).slice(0,8);
    if(!q||o.length<2)throw'A poll needs a question and at least 2 options';
    addM({c,f:p,t:'📊 '+q,poll:{o:o.map(t=>({t,v:[]})),mu:!!b.mu},...xp(c)});save();push(m,{e:'sync'});return{}}
  case'vote':{const x=D.msgs.find(y=>y.id==b.id);if(!x||!x.poll||!mem(x.c).includes(p))throw'Not allowed';
    const op=x.poll.o[+b.i];if(!op)throw'Bad option';const had=op.v.includes(p);
    if(!x.poll.mu)x.poll.o.forEach(z=>z.v=z.v.filter(u=>u!=p));else if(had)op.v=op.v.filter(u=>u!=p);
    if(!had)op.v.push(p);save();push(mem(x.c),{e:'sync'});return{}}
  case'block':{const u=nm(b.u);if(!D.profiles[u]||u==p)throw'User not found';const a=D.blocks[p]=D.blocks[p]||[],i=a.indexOf(u);
    if(b.on&&i<0)a.push(u);if(!b.on&&i>=0)a.splice(i,1);save();push([p],{e:'sync'});return{}}
  case'clr':{const c=String(b.c),m=mem(c);if(!m.includes(p))throw'No access';
    if(c[0]=='g'&&role(D.groups[c.slice(2)],p)=='member')throw'Admins only';
    D.msgs=D.msgs.filter(x=>x.c!=c);delete D.pins[c];save();push(m,{e:'sync'});return{}}
  case'ttl':{const c=String(b.c),m=mem(c),v=[3600,86400,604800].includes(+b.s)?+b.s:0;if(!m.includes(p))throw'No access';
    if(c[0]=='g'&&role(D.groups[c.slice(2)],p)=='member')throw'Admins only';
    if(v)D.ttl[c]=v;else delete D.ttl[c];
    sys(c,p+(v?' set auto-delete to '+({3600:'1 hour',86400:'1 day',604800:'1 week'})[v]:' turned off auto-delete'));save();push(m,{e:'sync'});return{}}
  case'gset':{adm();const n=String(b.name||'').trim().slice(0,40),ds=String(b.desc||'').trim().slice(0,200);if(!n)throw'Group name is required';
    if(n!=g.name)sys('g:'+g.id,p+' renamed the group to '+n);g.name=n;g.desc=ds;save();push(g.members,{e:'sync'});return{}}
  case'pw':{const L2=D.logins[L];if(hash(String(b.old||''),L2.salt)!==L2.hash)throw'Current password is wrong';
    const nw=String(b.nw||'');if(nw.length<4)throw'Password is too short (min 4)';
    L2.salt=cr.randomBytes(16).toString('hex');L2.hash=hash(nw,L2.salt);
    for(const k of Object.keys(D.tokens))if(D.tokens[k]==L&&k!=b.token)delete D.tokens[k];save();return{}}
  case'delacc':{const LL=D.logins[L];if(!LL)throw'Not found';if(hash(String(b.pw||''),LL.salt)!==LL.hash)throw'Wrong password';
    for(const g of Object.values(D.groups)){if(LL.profiles.includes(g.owner)){rm(g,g.members);continue}
      g.members=g.members.filter(x=>!LL.profiles.includes(x));g.admins=g.admins.filter(x=>!LL.profiles.includes(x))}
    for(const u of LL.profiles){delete D.profiles[u];delete D.pf[u];delete D.friends[u];delete D.blocks[u];delete D.seen[u];delete D.pins[u]}
    for(const k of Object.keys(D.friends)){const f=D.friends[k];f.f=f.f.filter(x=>!LL.profiles.includes(x));f.i=f.i.filter(x=>!LL.profiles.includes(x));f.o=f.o.filter(x=>!LL.profiles.includes(x))}
    D.msgs=D.msgs.filter(m=>!LL.profiles.includes(m.f));
    for(const t of Object.keys(D.tokens))if(D.tokens[t]==L)delete D.tokens[t];
    delete D.logins[L];save();return{}}
  case'rcGen':{const LL=D.logins[L];if(!LL)throw'Not found';const codes=[...Array(8)].map(()=>cr.randomBytes(4).toString('hex').replace(/^(.{4})/,'$1-'));LL.rc=codes.map(recHash);save();return{codes}}
  case'totpSetup':{const sec=b32e(cr.randomBytes(20));PENDSET[L]=sec;return{secret:sec}}
  case'totpEnable':{const sec=PENDSET[L];if(!sec)throw'Start the setup again';if(!otpOk({secret:sec,last:0},b.code))throw'Wrong code, try again';
    const codes=[...Array(8)].map(()=>cr.randomBytes(4).toString('hex').replace(/^(.{4})/,'$1-'));
    D.logins[L].otp={secret:sec,on:true,last:0,rec:codes.map(recHash)};delete PENDSET[L];save();return{codes}}
  case'totpOff':{const LL=D.logins[L];if(!LL.otp)throw'Two-step verification is not on';if(hash(String(b.pw||''),LL.salt)!==LL.hash)throw'Wrong password';delete LL.otp;save();return{}}
  case'report':{const c=String(b.c||''),m=D.msgs.find(x=>x.id==b.id&&x.c==c);if(!m||!mem(c).includes(p))throw'Cannot report';
    (D.reports=D.reports||[]).push({by:p,c,id:m.id,from:m.f,reason:String(b.reason||'').slice(0,60),ts:Date.now()});if(D.reports.length>500)D.reports.splice(0,100);save();return{}}
  case'sched':{const c=String(b.c||''),m=mem(c),t=String(b.t||'').trim().slice(0,2000),at=+b.at;
    if(!t||!m.includes(p))throw'Cannot schedule';if(!(at>Date.now()+30000)||at>Date.now()+30*864e5)throw'Pick a time between 1 minute and 30 days ahead';
    D.sched=D.sched||[];if(D.sched.filter(x=>x.f==p).length>=50)throw'Too many scheduled messages (max 50)';
    dmOk(c,p);D.sched.push({id:cr.randomBytes(6).toString('hex'),f:p,c,t,at});save();return{}}
  case'schedlist':return{items:(D.sched||[]).filter(x=>x.f==p).map(({id,c,t,at})=>({id,c,t,at}))};
  case'schedcancel':{D.sched=(D.sched||[]).filter(x=>!(x.f==p&&x.id==String(b.id)));save();return{}}
  case'msg':{const t=String(b.t||'').trim().slice(0,2000),m=mem(String(b.c));
    if(!t||!m.includes(p))throw'Cannot send';
    const cg=String(b.c)[0]=='g'&&D.groups[String(b.c).slice(2)];if(cg&&cg.channel&&role(cg,p)=='member')throw'Only admins can post in this channel';
    if(t.startsWith('img:')&&!IM[t.slice(4)])throw'Image not found';
    if(t.startsWith('vc:')&&!/^vc:[0-9a-f]{16}$/.test(t)||t.startsWith('vc:')&&!IM[t.slice(3)])throw'Voice not found';
    if(t.startsWith('gif:')&&!/^gif:https:\/\/[^\s<>"']{4,480}$/.test(t))throw'Bad GIF link';
    dmOk(String(b.c),p);
    const rp=b.r?D.msgs.find(x=>x.id==b.r&&x.c==b.c):null;
    addM({c:b.c,f:p,t,...(rp?{r:rp.id}:{}),...xp(b.c)});
    save();push(m,{e:'sync'});return{}}
  case'del':{const i=D.msgs.findIndex(x=>x.id==b.id),m=D.msgs[i];if(!m)return{};
    const ok=m.f==p||(m.c[0]=='g'&&D.groups[m.c.slice(2)]&&role(D.groups[m.c.slice(2)],p)!='member');
    if(!ok)throw'Not allowed';D.msgs.splice(i,1);save();push(mem(m.c),{e:'sync'});return{}}
  case'edit':{const m=D.msgs.find(x=>x.id==b.id),t=String(b.t||'').trim().slice(0,2000);
    if(!m||m.s||m.poll||m.f!=p||!t||/^(sk|img|gif):/.test(m.t))throw'Not allowed';if(m.t!=t){m.t=t;m.e=1;save();push(mem(m.c),{e:'sync'})}return{}}
  case'react':{const m=D.msgs.find(x=>x.id==b.id),e=String(b.emo||'');
    if(!m||m.s||!mem(m.c).includes(p)||!['👍','❤️','😂','🔥','😮','😢'].includes(e))throw'Not allowed';
    m.rx=m.rx||{};const a=m.rx[e]=m.rx[e]||[],i=a.indexOf(p);if(i<0)a.push(p);else a.splice(i,1);
    if(!a.length)delete m.rx[e];if(!Object.keys(m.rx).length)delete m.rx;save();push(mem(m.c),{e:'sync'});return{}}
  case'read':{const c=String(b.c),m=mem(c),id=+b.id||0;if(!m.includes(p))throw'No access';const k=c+'#'+p;
    if(id>(D.reads[k]||0)){D.reads[k]=id;save();push(m.filter(x=>x!=p),{e:'rd',c,f:p,id})}return{}}
  case'typing':{const m=mem(String(b.c));if(m.includes(p))push(m.filter(x=>x!=p),{e:'typing',c:b.c,f:p});return{}}
  case'gsig':{const gid=String(b.g||'').replace(/^g:/,''),gr=D.groups[gid],to=String(b.to||'');
    if(!gr||!gr.members.includes(p)||!gr.members.includes(to))throw'Not allowed';
    push([to],{e:'gsig',f:p,g:'g:'+gid,d:b.d});return{}}
  case'sig':{if(!fr(p).f.includes(b.to))throw'You are not friends';push([b.to],{e:'sig',f:p,d:b.d});return{}}
  case'actv':{const c=String(b.c),m=mem(c);if(!m.includes(p))throw'No access';
    if(c[0]=='d'&&!fr(p).f.includes(m.find(x=>x!=p)))throw'You are not friends';
    push(m.filter(x=>x!=p),{e:'actv',f:p,c,d:b.d});return{}}
  case'fadd':{const t=nm(b.to);if(!D.profiles[t]||t==p)throw'User not found';
    const a=fr(p),o=fr(t);if(a.f.includes(t))throw'Already friends';
    if(a.i.includes(t)){a.i=a.i.filter(x=>x!=t);o.o=o.o.filter(x=>x!=p);a.f.push(t);o.f.push(p)}
    else if(!a.o.includes(t)){a.o.push(t);o.i.push(p)}
    save();push([p,t],{e:'sync'});return{}}
  case'facc':{const t=b.to,a=fr(p),o=fr(t);if(!a.i.includes(t))throw'No such request';
    a.i=a.i.filter(x=>x!=t);o.o=o.o.filter(x=>x!=p);a.f.push(t);o.f.push(p);save();push([p,t],{e:'sync'});return{}}
  case'fdec':case'frem':{const t=b.to,a=fr(p),o=fr(t);
    for(const k of['f','i','o']){a[k]=a[k].filter(x=>x!=t);o[k]=o[k].filter(x=>x!=p)}
    save();push([p,t],{e:'sync'});return{}}
  case'gnew':{const n=String(b.name||'').trim().slice(0,40);if(!n)throw'Group name is required';
    const id=String(D.n++);
    D.groups[id]={id,name:n,owner:p,admins:[],members:[p],pub:!!b.pub,channel:!!b.ch,code:cr.randomBytes(4).toString('hex')};
    sys('g:'+id,p+' created the group');save();push([p],{e:'sync'});return{id:'g:'+id}}
  case'gjoin':{const h=b.id?D.groups[b.id]:Object.values(D.groups).find(x=>x.code==String(b.code||'').trim());
    if(!h||(b.id&&!h.pub))throw'Group not found';if(h.members.includes(p))throw'Already a member';
    h.members.push(p);sys('g:'+h.id,p+' joined');save();push(h.members,{e:'sync'});return{id:'g:'+h.id}}
  case'gadd':{adm();const u=nm(b.u);if(!D.profiles[u])throw'User not found';if(g.members.includes(u))throw'Already a member';
    g.members.push(u);sys('g:'+g.id,p+' added '+u);save();push(g.members,{e:'sync'});return{}}
  case'gkick':{adm();const u=b.u;if(!g.members.includes(u)||u==g.owner||(g.admins.includes(u)&&p!=g.owner))throw'Not allowed';
    g.members=g.members.filter(x=>x!=u);g.admins=g.admins.filter(x=>x!=u);sys('g:'+g.id,p+' removed '+u);
    save();push([...g.members,u],{e:'sync'});return{}}
  case'gadm':{if(!g||g.owner!=p)throw'Owner only';if(!g.members.includes(b.u)||b.u==p)throw'Bad user';
    g.admins=g.admins.filter(x=>x!=b.u);if(b.on)g.admins.push(b.u);
    sys('g:'+g.id,b.u+(b.on?' is now an admin':' is no longer an admin'));save();push(g.members,{e:'sync'});return{}}
  case'gpub':{if(!g||g.owner!=p)throw'Owner only';g.pub=!!b.on;save();push(g.members,{e:'sync'});return{}}
  case'gleave':{if(!g||!g.members.includes(p))throw'Not a member';const all=[...g.members];
    g.members=g.members.filter(x=>x!=p);g.admins=g.admins.filter(x=>x!=p);
    if(!g.members.length)return rm(g,all);
    if(g.owner==p){g.owner=g.admins[0]||g.members[0];g.admins=g.admins.filter(x=>x!=g.owner)}
    sys('g:'+g.id,p+' left');save();push(all,{e:'sync'});return{}}
  case'gdel':{if(!g||g.owner!=p)throw'Owner only';return rm(g,g.members)}
  }
  throw'Unknown action'}

setInterval(()=>{const now=Date.now(),gone=D.msgs.filter(m=>m.x&&m.x<now);if(!gone.length)return;
  D.msgs=D.msgs.filter(m=>!(m.x&&m.x<now));save();for(const c of new Set(gone.map(m=>m.c)))push(mem(c),{e:'sync'})},30000);
