const srv=http.createServer((q,s)=>{
  const u=new URL(q.url,'http://x');
  if(u.pathname=='/events'){const L=D.tokens[u.searchParams.get('token')];
    if(!L){s.writeHead(401);return s.end()}
    s.writeHead(200,{'Content-Type':'text/event-stream','Cache-Control':'no-cache',Connection:'keep-alive','X-Accel-Buffering':'no'});
    s.write(': ok\n\n');(streams[L]=streams[L]||new Set()).add(s);pres(L);
    const k=setInterval(()=>s.write(': ping\n\n'),20000);
    q.on('close',()=>{clearInterval(k);streams[L].delete(s);if(!streams[L].size&&D.logins[L]){for(const p of D.logins[L].profiles)D.seen[p]=Date.now();save()}pres(L)});return}
  if(u.pathname=='/.well-known/assetlinks.json'){s.writeHead(200,{'Content-Type':'application/json'});return s.end(process.env.ASSETLINKS||'[]')}
  if(u.pathname=='/auth/google'){return gStart(q,s)}
  if(u.pathname=='/auth/google/callback'){return gCallback(q,s,u)}
  if(u.pathname=='/terms'){s.writeHead(200,{'Content-Type':'text/html; charset=utf-8'});return s.end(TERMS)}
  if(u.pathname=='/privacy'){s.writeHead(200,{'Content-Type':'text/html; charset=utf-8'});return s.end(PRIVACY)}
  if(u.pathname=='/manifest.json'){s.writeHead(200,{'Content-Type':'application/manifest+json'});return s.end(MANIFEST)}
  if(u.pathname=='/sw.js'){s.writeHead(200,{'Content-Type':'text/javascript','Cache-Control':'no-cache'});return s.end(SW)}
  const im=u.pathname.match(/^\/icon-(192|512)\.png$/);if(im){s.writeHead(200,{'Content-Type':'image/png','Cache-Control':'public,max-age=86400'});return s.end(ICON[im[1]])}
  if(u.pathname.startsWith('/img/')){const o=IM[u.pathname.slice(5)];if(!o){s.writeHead(404);return s.end()}
    const i=o.d.indexOf(','),mt=o.d.slice(5,o.d.indexOf(';'));
    s.writeHead(200,{'Content-Type':mt,'Cache-Control':'public,max-age=31536000,immutable','X-Content-Type-Options':'nosniff'});return s.end(Buffer.from(o.d.slice(i+1),'base64'))}
  if(q.method=='POST'&&u.pathname=='/api'){let d='';
    q.on('data',c=>{d+=c;if(d.length>2e5)q.destroy()});
    q.on('end',async()=>{let r;const ip=(q.headers['x-forwarded-for']||q.socket.remoteAddress||'').split(',')[0].trim();
      try{const b=JSON.parse(d);
        if((b.a=='reg'||b.a=='login'||b.a=='otp'||b.a=='pwreset')&&limited(ip))throw'Too many attempts. Try again in a few minutes.';if(b.a=='reg')r=reg(b);else if(b.a=='login')r=login(b);else if(b.a=='otp')r=otpLogin(b);else if(b.a=='pwreset')r=pwReset(b);else if(b.a=='gexch')r=gexch(b);else if(b.a=='gifs'){if(!D.tokens[b.token])throw'AUTH';r=await gifs(b)}
        else{const L=D.tokens[b.token];if(!L)throw'AUTH';
          if(b.a!='addp'&&!D.logins[L].profiles.includes(b.as))throw'Bad profile';
          r=act(L,b.as,b)}}
      catch(e){if(typeof e=='string')r={err:e};else{console.error(e);r={err:'Server error'}}}
      s.writeHead(200,{'Content-Type':'application/json'});s.end(JSON.stringify(r))});return}
  fs.readFile(path.join(__dirname,'public','index.html'),(e,h)=>{
    if(e){s.writeHead(404);return s.end('public/index.html not found')}
    s.writeHead(200,{'Content-Type':'text/html; charset=utf-8','X-Content-Type-Options':'nosniff','X-Frame-Options':'SAMEORIGIN','Referrer-Policy':'same-origin'});s.end(String(h).replace(/__ORIGIN__/g,'https://'+(q.headers.host||'localhost')).replace(/__DL_WIN__/g,process.env.DL_WIN||'').replace(/__DL_MAC__/g,process.env.DL_MAC||'').replace(/__DL_LINUX__/g,process.env.DL_LINUX||'').replace(/__GON__/g,GON?'1':''))})
});
